--- a/internal/report/split.go
+++ b/internal/report/split.go
@@ -8,12 +8,26 @@ type Row struct {
 	Amount int
 }

-func Split(rows []Row) []Row {
-	return rows
+const pageSize = 10
+
+func Split(rows []Row) ([]Row, []Row) {
+	sort.Slice(rows, func(i, j int) bool {
+		return rows[i].At.Before(rows[j].At)
+	})
+
+	if len(rows) <= pageSize {
+		return rows, nil
+	}
+
+	head := rows[:pageSize]
+	tail := rows[pageSize:]
+
+	head = append(head, Row{Kind: "total", Amount: sum(rows)})
+
+	return head, tail
 }

 func sum(rows []Row) int {
 	total := 0
 	for _, r := range rows {
 		total += r.Amount
 	}
 	return total
 }
